import {WEAPONS,MONSTERS,ITEMS,getWeapon} from './content.js';
export function createSave(name,gender){name=String(name).trim();if(!name||[...name].length>12)throw Error('请输入 1–12 个字符的猎人名字');if(!['male','female'].includes(gender))throw Error('请选择猎人性别');return {version:1,name,gender,weapon:'ls',levels:Object.fromEntries(WEAPONS.map(w=>[w.id,1])),armor:1,money:0,items:Object.fromEntries(Object.keys(ITEMS).map(k=>[k,0])),unlocked:0,wins:[0,0,0],claimed:[]};}
export function stats(s){return {hp:100+(s.armor-1)*20,defense:(s.armor-1)*2,attack:Math.round(getWeapon(s.weapon).attack*(1+(s.levels[s.weapon]-1)*.22))};}
export function recipe(s,type){const level=type==='armor'?s.armor:s.levels[s.weapon];const m=MONSTERS[level<=2?0:level===3?1:2];return {level,money:level*80,items:{[m.common]:level*2,...(level===4?{[m.rare]:1}:{})}};}
export function upgrade(s,type){if(!['armor','weapon'].includes(type))return {ok:false,reason:'未知装备'};const r=recipe(s,type);if(r.level>=5)return {ok:false,reason:'已达最高等级'};if(s.money<r.money||Object.entries(r.items).some(([k,v])=>s.items[k]<v))return {ok:false,reason:'素材或金钱不足，再去狩猎吧'};s.money-=r.money;for(const [k,v]of Object.entries(r.items))s.items[k]-=v;if(type==='armor')s.armor++;else s.levels[s.weapon]++;return {ok:true};}
export function rewardHunt(s,index,id,rng=Math.random){if(s.claimed.includes(id))return null;const m=MONSTERS[index];if(!m)throw Error('未知任务');const drops={[m.common]:2+Math.floor(Math.min(.999999,Math.max(0,rng()))*3)};if(rng()<.35)drops[m.rare]=1;for(const[k,v]of Object.entries(drops))s.items[k]+=v;s.money+=m.reward;s.wins[index]++;s.unlocked=Math.max(s.unlocked,Math.min(2,index+1));s.claimed.push(id);s.claimed=s.claimed.slice(-100);return {money:m.reward,drops};}
const integer=(n,min,max)=>Number.isInteger(n)&&n>=min&&n<=max;
export function parseSave(raw){const s=JSON.parse(raw);if(!s||s.version!==1)throw Error('不支持的存档版本');const clean=createSave(s.name,s.gender);if(typeof s.name!=='string'||!WEAPONS.some(w=>w.id===s.weapon)||!integer(s.armor,1,5)||!integer(s.money,0,1e9)||!integer(s.unlocked,0,2))throw Error('存档数据不合法');clean.weapon=s.weapon;clean.armor=s.armor;clean.money=s.money;clean.unlocked=s.unlocked;for(const w of WEAPONS){if(!integer(s.levels?.[w.id],1,5))throw Error('武器数据不合法');clean.levels[w.id]=s.levels[w.id];}for(const k of Object.keys(ITEMS)){if(!integer(s.items?.[k],0,1e7))throw Error('素材数据不合法');clean.items[k]=s.items[k];}if(!Array.isArray(s.wins)||s.wins.length!==3||s.wins.some(v=>!integer(v,0,1e7)))throw Error('任务数据不合法');clean.wins=[...s.wins];if(!Array.isArray(s.claimed)||s.claimed.length>100||s.claimed.some(v=>typeof v!=='string'||v.length>100))throw Error('结算数据不合法');clean.claimed=[...s.claimed];return clean;}
